/**
 * ЭКЗАМЕН РОЛИ «КУПИТЬ / ПРОДАТЬ» (владелец 20.11.2026: «чтобы покупатели не путались с продавцами… с высокой вероятностью
 * никогда не путаться»). Первые реплики клиентов с прода (WhatsApp, Instagram, Facebook; 21.10–21.11.2026 и выборка
 * 20.11.2026) — без имён, номеров, адресов и сумм: адрес и район заменены словом «<район>», сумма — «<сумма>». Разметка — по
 * смыслу слов клиента, тема рекламы на разметку не влияет (на рекламе «для собственников» пишут и покупатели).
 *
 * Метки: buyer — покупает (или спрашивает о нашем объекте); seller — продаёт своё; both — и продать, и купить; ask — роль из
 * слов не следует (приветствие, кнопка рекламы, «сколько стоят услуги?», мусор): бот спрашивает «купить или продать?», роли
 * и заявки нет; none — не покупатель и не продавец (вакансия, аренда, спам, просьба денег).
 * `real: false` — строки, которых в выборке не было, дописаны для классов из разбора (аренда, работа, торг).
 */
export type RoleExamLabel = "buyer" | "seller" | "both" | "ask" | "none";
export interface RoleExamRow { text: string; label: RoleExamLabel; real: boolean }

const r = (text: string, label: RoleExamLabel): RoleExamRow => ({ text, label, real: true });
const s = (text: string, label: RoleExamLabel): RoleExamRow => ({ text, label, real: false });

